    body += shown(2, [[[95, 46], [72, 44], [58, 40]], [[104, 44], [108, 39], [113, 37]]].map((p, i) => drawArrow(2, smooth(PP(v, p), 2), C.red, { w: 5, delay: 0.3 + 0.2 * i })).join(''), 3);
    // 3칸: 가장 넓을 때
    body += shown(3, terr(v, m.clip, [MAXE], C.red, { op: 0.34, cls: 'fin fin3' }));
    body += shown(3, [[[70, 50], [50, 54], [36, 53]], [[60, 40], [50, 36], [42, 35.5]], [[112, 36], [115, 30], [113, 25]]].map((p, i) => drawArrow(3, smooth(PP(v, p), 2), C.red, { w: 5, delay: 0.3 + 0.2 * i })).join(''));
    // 4칸: 테두리 반짝, 이름
    body += shown(4, flashT(v, m.clip, [MAXE], C.red));
    body += at(4, 'pop', tag(...P(v, 84, 47), '몽골 제국', RED, { size: 22 }), 0.4);
